                r.setDiscr(discr);

                recruiterService.addRecruiter(r);

            } else { // CANDIDATE
                Integer years = null;
                String yearsText = txtExperienceYears.getText() == null ? "" : txtExperienceYears.getText().trim();
                if (!yearsText.isEmpty()) {
