                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?)";

        String safePassword = password != null ? password : "default123";
        String hashed = PasswordUtil.hash(safePassword);
        String roleValue = role != null ? role : "USER";
        String rolesJson = "[\"ROLE_" + roleValue + "\"]";
